<?php if ($enabled && is_array($user)): ?><script>(()=>{const leader=<?= ($config['leave_verification_mode'] ?? 'any_employee') === 'leader' ? 'true' : 'false' ?>,box=document.querySelector('.leave-verifier'),heading=box.querySelector('.leave-heading'),group=document.createElement('div');heading.querySelector('h2').textContent=leader?'Xác thực tổ trưởng':'Gửi link xác thực';heading.querySelector('p').textContent=leader?'Nhập Mã NV tổ trưởng, sau đó gửi link để tổ trưởng đăng nhập xác thực.':'Tạo link và gửi cho người phụ trách tại bộ phận để họ đăng nhập xác nhận.';group.className='leave-link-note';group.innerHTML=leader?'<label class="form-label">Mã NV tổ trưởng</label><input class="form-input" name="expected_verifier_id" required autocomplete="off" placeholder="Nhập Mã NV tổ trưởng"><div class="leave-note-copy">Chỉ đúng tổ trưởng có Mã NV này mới xác thực được đơn.</div>':'<div class="leave-note-title">Lưu ý</div><div class="leave-note-copy">Nhấn “Gửi yêu cầu xác thực”, sau đó gửi link cho người phụ trách. Đơn chỉ được chuyển quản lý khi người nhận đăng nhập xác thực thành công.</div>';box.insertBefore(group,box.querySelector('.leave-grid'))})();</script><?php endif; ?>
<?php if ($enabled && is_array($user)): ?><script>(()=>{const applicant=document.querySelector('.leave-applicant'),type=document.querySelector('[name="leave_type"]');if(applicant)applicant.innerHTML='<span>Người nộp đơn</span><div><strong>Họ tên: <?= $safe($user['name'] ?? 'Chưa cập nhật') ?></strong><small>Mã NV: <?= $safe($user['id'] ?? '') ?> · Bộ phận: <?= $safe($user['department'] ?? '') ?></small></div>';if(type){const group=type.closest('.form-group');if(group)group.remove();document.querySelector('.leave-grid')?.classList.add('leave-grid--dates');}})();</script><?php endif; ?>
