<?php if ($enabled && is_array($user)): ?><script>const csrf=<?= json_encode($csrf) ?>,result=document.getElementById('leave-result'),list=document.getElementById('leave-list'),count=document.getElementById('leave-count'),form=document.getElementById('leave-form'),verifier=document.querySelector('.leave-verifier');const mode=document.createElement('select');mode.className='form-input';mode.innerHTML='<option value="direct">Xác thực ngay trên thiết bị này</option><option value="link">Tạo link để tự gửi người xác thực</option>';const modeGroup=document.createElement('div');modeGroup.className='form-group';modeGroup.innerHTML='<label class="form-label">Cách xác thực</label>';modeGroup.appendChild(mode);verifier.insertBefore(modeGroup,verifier.querySelector('.leave-grid'));const verifierFields=verifier.querySelector('.leave-grid');function syncMode(){const link=mode.value==='link';verifierFields.style.display=link?'none':'';verifierFields.querySelectorAll('input').forEach(x=>x.required=!link)}mode.onchange=syncMode;function esc(v){return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[s]))}function tag(s){let c=s==='Đã duyệt'?'approved':s==='Từ chối'?'rejected':'pending';return `<span class="leave-status ${c}">${esc(s)}</span>`}function shares(url){const text='Vui lòng mở link để xác thực đơn xin nghỉ: '+url,enc=encodeURIComponent(url),body=encodeURIComponent(text);result.innerHTML=`<div class="leave-share"><strong>Gửi link xác thực cho người duyệt</strong><p>Link dùng một lần và hết hạn sau 24 giờ.</p><button data-copy>Sao chép link</button><a target="_blank" href="https://www.facebook.com/sharer/sharer.php?u=${enc}">Messenger</a><a target="_blank" href="https://zalo.me/share?url=${enc}">Zalo</a><a target="_blank" href="https://social-plugins.line.me/lineit/share?url=${enc}">LINE</a><a href="sms:?body=${body}">SMS</a></div>`;result.querySelector('[data-copy]').onclick=async()=>{await navigator.clipboard.writeText(url);result.querySelector('[data-copy]').textContent='Đã sao chép'}}async function load(){try{let f=new FormData();f.append('action','leave_list');f.append('csrf_token',csrf);let j=await fetch('index.php',{method:'POST',body:f}).then(r=>r.json());if(!j.success)throw Error();count.textContent=`${j.requests.length} đơn`;list.innerHTML=!j.requests.length?'<div class="leave-list-empty">Chưa có đơn nào. Đơn bạn gửi sẽ xuất hiện tại đây.</div>':j.requests.map(x=>`<article class="leave-request"><div class="leave-date"><b>${esc(x['TỪ NGÀY'])}</b><span>đến ${esc(x['ĐẾN NGÀY'])}</span></div><div class="leave-request-main"><strong>${esc(x['LOẠI NGHỈ'])}</strong><p>${esc(x['LÝ DO'])}</p><small>Đã xác thực bởi ${esc(x['TÊN NGƯỜI XÁC THỰC'])||'đang chờ'} · ${esc(x['THỜI GIAN XÁC THỰC'])}</small></div>${tag(x['TRẠNG THÁI'])}</article>`).join('')}catch(_){count.textContent='Lỗi tải';list.innerHTML='<div class="leave-list-empty">Không thể tải lịch sử đơn.</div>'}}form.addEventListener('submit',async e=>{e.preventDefault();result.className='leave-feedback';result.textContent='Đang xử lý đơn…';let f=new FormData(form),share=mode.value==='link';f.append('action',share?'leave_create_share':'leave_submit');f.append('csrf_token',csrf);try{let j=await fetch('index.php',{method:'POST',body:f}).then(r=>r.json());result.className='leave-feedback '+(j.success?'is-success':'is-error');if(j.success&&share){const url=new URL('index.php?page=leave_verify',location.href);url.searchParams.set('token',j.token);shares(url.toString());form.reset();syncMode();load()}else{result.textContent=j.message;if(j.success){form.reset();load()}}}catch(_){result.className='leave-feedback is-error';result.textContent='Không thể gửi đơn. Vui lòng thử lại.'}});load();</script><?php endif; ?></body></html>
